function validateVideo(file){return new Promise((resolve,reject)=>{const v=document.createElement('video'),url=URL.createObjectURL(file),timer=setTimeout(()=>done(Error('Video metadata could not be read.')),8000);function done(err){clearTimeout(timer);URL.revokeObjectURL(url);v.removeAttribute('src');err?reject(err):resolve()}v.preload='metadata';v.onloadedmetadata=()=>done(validLoop(v.duration)?null:Error('Your loop must be 15 seconds or shorter.'));v.onerror=()=>done(Error('This video format cannot be played. Try MP4 or WebM.'));v.src=url})}
function editScene(){modal(`<h2>A new place to begin.</h2><form id="sceneForm"><label>Scene name<input name="name" required maxlength="80"></label><label>What is happening here?<textarea name="details" required maxlength="4000"></textarea></label><label>Background picture or video<input name="image" type="file" accept="image/png,image/jpeg,image/webp,video/mp4,video/webm"></label><p class="footerNote">A video must be 15 seconds or shorter and plays silently on a loop. Do not use a green screen here: the background shows behind a green-screen character.</p><button class="primary wide">Save scene</button></form>`);$('#sceneForm').onsubmit=async e=>{e.preventDefault();const f=e.target,id=crypto.randomUUID();try{const file=f.image.files[0];if(file&&isVideo(file.type)){if(file.size>20e6)throw Error('Choose a video under 20 MB.');await validateVideo(file)}else if(file&&(!/^image\/(png|jpeg|webp)$/.test(file.type)||file.size>8e6))throw Error('Choose an image under 8 MB, or a short video.');const s={id,name:f.elements.name.value.trim(),details:f.details.value.trim(),art:file?await putMedia('media-'+id,file):''};if(!s.name)throw Error('Enter a scene name.');state.scenes.push(s);state.selection.scene=id;save();$('#modal').close();render()}catch(err){toast(err.message)}}}
