function voiceList(){const list=shownVoices(),full=view==='voices',sel=state.selection.voice;return `<div class="row between"><span class="tag">Cloned voices</span><button id="sample" class="mini primary">＋ Clone a voice</button></div><p class="sub">Record or upload 5 to 10 seconds of clear speech. The clone is made on this device.</p><div class="list">${state.samples.length?state.samples.map(s=>`<div class="voice ${sel==='clone:'+s.id?'selected':''}"><button class="choose" data-clone="${esc(s.id)}">${esc(s.name)}<small>Cloned voice · made on this device</small></button><button class="play" data-clonepreview="${esc(s.id)}" aria-label="Preview ${esc(s.name)}">▶</button>${full?`<button class="play" data-cloneremove="${esc(s.id)}" aria-label="Remove ${esc(s.name)}">×</button>`:''}</div>`).join(''):'<div class="empty">No cloned voices yet.</div>'}</div>${full?`<div class="bookCard"><span class="eyebrow">VOICE TOOL</span><label>Type a line to hear it in the selected cloned voice<textarea id="cloneText" maxlength="1000">${esc(cloneLine)}</textarea></label><div class="actions"><button id="cloneSpeak" class="primary">Speak</button><button id="cloneStop">Stop</button><button id="cloneSave">Save WAV</button></div></div>`:''}<p class="footerNote">The first use downloads the open-source Pocket TTS voice model. Your sample and text are not uploaded. Only clone a voice you own or have permission to use.</p><div class="row between" style="margin-top:26px"><span class="tag">Device voices</span><button id="refreshVoices" class="mini secondary">Refresh</button></div><p class="sub">Your browser’s built-in voices. Preview before choosing.</p><div class="list">${list.length?list.map(v=>`<div class="voice ${sel===v.voiceURI?'selected':''}"><button class="choose" data-voice="${esc(v.voiceURI)}">${esc(v.name)}<small>${esc(v.lang)} · ${v.localService?'On-device':'Browser service'}</small></button><button class="play" data-preview="${esc(v.voiceURI)}" aria-label="Preview ${esc(v.name)}">▶</button></div>`).join(''):'<div class="empty">No device voices loaded yet. Tap Refresh, or continue with text.</div>'}</div>${voices.length>list.length?`<p><button id="moreVoices" class="mini secondary">Show all ${voices.length} voices</button></p>`:''}`}
