async function ensureLooks(s){const cfg=state.brainCfg;if(cfg?.mode!=='remote')return;const jobs=[];const want=(o,key,kind)=>{if(!o||!key||o.lookOf===key||o.lookEdited)return;const src=mediaURL(key);if(!src)return;jobs.push((kind==='frame'||isVideo(kindOf(key))?firstFrame(src):fetch(src).then(r=>r.blob())).then(b=>brain.describeImage(cfg,b,kind==='frame'?'character':kind)).then(t=>{o.lookOf=key;if(t)o.look=t}).catch(()=>{}))};const see=c=>c.image&&mediaURL(c.image)?want(c,c.image,'character'):want(c,c.loop,'frame');see(findCast(s.partner));if(s.player!==s.partner)see(findCast(s.player));const sc=findScene(s.scene);want(sc,sc.art,'scene');if(!jobs.length)return;toast('Looking at the pictures…',true);await Promise.race([Promise.all(jobs),new Promise(r=>setTimeout(r,12000))]);save();if(toast.status)$('#toast').style.display='none'}
const brainCtx=(s,extra)=>{const c=findCast(s.partner),you=findCast(s.player),scene=findScene(s.scene);return {name:c.name,role:c.role,persona:c.persona,look:c.look,scene:scene.name,sceneDetails:scene.details,sceneLook:scene.look,player:you.name,playerPersona:you.id==='you'?'':you.persona,playerLook:you.look,messages:extra?[...s.messages,{role:'user',text:extra}]:s.messages.slice()}};
