// ---- Story script: she speaks the next prepared line. Nothing is generated at this moment, so it is instant.
function storyNext(s){const plan=s.plan,show=()=>{if(view==='chat'&&currentSession()?.id===s.id)renderChat()};if(!plan?.beats?.length){awaiting=false;return}if(plan.at>=plan.beats.length){s.story=false;save();awaiting=false;show();toast('That was the last line of the story you planned. Switch on AI brain to keep talking, or write more lines in Book.',true);return listenLoop()}const b=plan.beats[plan.at++],line={role:'assistant',text:b.text,emotion:b.emotion,story:true};s.messages.push(line);save();show();emote(line);voiceReply(b.text,s)}
