function send(){const input=$('#message'),text=input.value.trim();if(!text)return;const s=currentSession();if(s.brain&&(thinking||brain.isBusy()))return toast('Still thinking about your last message.');s.messages.push({role:'user',text});input.value='';save();drawMessages();{const act=actionFor(text,findCast(s.partner).actions||[]);if(act)stage?.show(act)}{const l=(findScene(s.scene).links||[]).find(l=>l.words&&new RegExp(l.words,'i').test(text)&&/\b(go|walk|head|take|lead|follow|let'?s|move|show|back)\b/i.test(text));if(l&&stage)travelTo(s,l)}if(recognition){try{recognition.abort()}catch{}}if(s.brain){awaiting=true;hfSay('she is thinking…');return brainReply(s)}if(s.story&&s.plan?.beats?.length){awaiting=true;clearTimeout(replyTimer);replyTimer=setTimeout(()=>storyNext(s),250);return}if(s.demo){awaiting=true;clearTimeout(replyTimer);replyTimer=setTimeout(()=>{const c=findCast(s.partner),r=demoReply(text,c.name,findScene(s.scene).name,s.messages.length);s.messages.push({role:'assistant',text:r,demo:true});save();if(view==='chat'&&currentSession()?.id===s.id)drawMessages();voiceReply(r,s)},550)}else{toast('Message saved. AI replies are not connected; add dialogue in Storybook.');listenLoop()}}
