function hfSay(t){const e=$('#hfStatus');if(e)e.textContent=handsFree?`Hands-free · ${t}`:document.body.classList.contains('call')?'Tap the mic and just talk':''}
// Mic. One tap (hands-free off) dictates one message into the box, as before.
// Hands-free: words appear in the box as you speak, and the message sends itself once you have been quiet for a moment.
