  r.onstart=()=>{$('#mic')?.classList.add('live');if($('#message'))$('#message').placeholder='Listening…';hfSay('listening… just talk');if(!hf)toast('Listening… speak your message. Tap the mic again to stop.')};
  r.onresult=e=>{const box=$('#message');if(!box||sent)return;const lastRes=e.results[e.results.length-1];let t=android?lastRes[0].transcript:[...e.results].map(x=>x[0].transcript).join(' ');t=t.replace(/\s+/g,' ').trim();if(!hf){if(lastRes.isFinal!==false&&t)box.value=box.value.trim()?box.value.trim()+' '+t:t;return}if(!t)return;heard=t;box.value=t;hfSay('hearing you…');clearTimeout(quiet);quiet=setTimeout(finish,1400);if(predict){clearTimeout(settle);if(t.split(' ').length>=3)settle=setTimeout(()=>prepareGuess(s0,t),450)}};
