function storyPlanCard(s){const p=s.plan||{},c=findCast(s.partner),n=p.beats?.length||0,clone_=(s.voice||'').startsWith('clone:');return `<div class="bookCard"><span class="eyebrow">STORY SCRIPT</span><p class="footerNote" style="margin-top:8px">Plan the story, then have ${esc(c.name)}’s lines written ahead of time. In chat she follows the script, so she answers at once, even in a cloned voice.</p>
  <label>What is this story about?<textarea id="planPremise" maxlength="1500" style="min-height:70px" placeholder="A sentence or two. Leave empty to let Auto decide.">${esc(p.premise||'')}</textarea></label>
  <label>Things that must happen, one per line<textarea id="planMust" maxlength="1500" style="min-height:70px" placeholder="Optional. For example: We find the hidden map.">${esc(p.must||'')}</textarea></label>
  <div class="grid" style="gap:10px"><label style="margin-top:10px">Genre<select id="planGenre"><option value="">Surprise me</option>${GENRES.map(x=>`<option ${p.genre===x?'selected':''}>${x}</option>`).join('')}</select></label><label style="margin-top:10px">Kind of story<select id="planShape"><option value="">Surprise me</option>${STORY_SHAPES.map(x=>`<option value="${x.id}" ${p.shape===x.id?'selected':''}>${x.name}</option>`).join('')}</select></label></div>
  <p class="footerNote" style="margin-top:8px">Each kind is a classic plot that is known to work: a hook, real stakes, a twist and a payoff. Only the bones are borrowed, never anyone else’s characters.</p>
  <button id="planAuto" class="secondary wide" style="border-color:#a88cff;color:#d9ccff">✦ Auto outline</button>
  <label>Intro<textarea id="planIntro" maxlength="800" style="min-height:60px">${esc(p.intro||'')}</textarea></label><label>Body<textarea id="planBody" maxlength="800" style="min-height:60px">${esc(p.body||'')}</textarea></label><label>Conclusion<textarea id="planEnd" maxlength="800" style="min-height:60px">${esc(p.conclusion||'')}</textarea></label>
  <label>Key events in order, one per line<textarea id="planEvents" maxlength="2500">${esc((p.events||[]).join('\n'))}</textarea></label>
  <label>How many lines should she have?<select id="planCount">${[8,12,18,24].map(k=>`<option ${k===(p.count||12)?'selected':''}>${k}</option>`).join('')}</select></label>
  <button id="planWrite" class="primary wide" style="margin-top:14px">Write ${esc(c.name)}’s lines</button>
  <label>${esc(c.name)}’s lines, one per row. You can edit them.<textarea id="planBeats" class="chapter" style="min-height:220px;font-size:15px" placeholder="Nothing written yet.">${esc(beatsToText(p.beats))}</textarea></label>
  <p class="footerNote" id="planStatus" style="margin:8px 0 0;color:var(--cyan)">${n?`${n} lines ready to use.`:''}${n&&clone_?' Prepare the voice so the cloned voice plays without waiting.':''}</p>
  <div class="actions"><button id="planVoice" ${n?'':'disabled'}>${clone_?'Prepare voice':'Voice: phone, no wait'}</button><button id="planUse" class="primary" ${n?'':'disabled'}>Start in chat</button></div></div>`}
function wireStoryPlan(s){const g=id=>$('#'+id),c=findCast(s.partner),say=t=>{if(g('planStatus'))g('planStatus').textContent=t};
  const read=()=>{const p=s.plan||(s.plan={at:0});p.premise=g('planPremise').value.trim();p.must=g('planMust').value.trim();p.intro=g('planIntro').value.trim();p.body=g('planBody').value.trim();p.conclusion=g('planEnd').value.trim();p.events=g('planEvents').value.split('\n').map(x=>x.trim()).filter(Boolean);p.count=+g('planCount').value;p.genre=g('planGenre').value;p.shape=g('planShape').value;p.beats=textToBeats(g('planBeats').value,c.name);if(p.at>p.beats.length)p.at=0;save();return p};
  const need=()=>{if(brainReady())return true;toast('This needs the AI brain. Open a chat, tap ⚙ and connect it, then come back.',true);return false};
  const busy=async(btn,label,fn)=>{const old=btn.textContent;btn.disabled=true;btn.textContent=label;try{await fn()}catch(err){toast(err.message,true)}finally{if(document.contains(btn)){btn.disabled=false;btn.textContent=old}}};
  for(const id of ['planPremise','planMust','planIntro','planBody','planEnd','planEvents','planBeats'])g(id).onchange=read;g('planCount').onchange=read;g('planGenre').onchange=read;g('planShape').onchange=read;
  g('planAuto').onclick=()=>{if(!need())return;busy(g('planAuto'),'Planning…',async()=>{const p=read();await ensureLooks(s).catch(()=>{});const genre=p.genre||pickFrom(GENRES,p.lastGenre),shape=STORY_SHAPES.find(x=>x.id===p.shape)||pickFrom(STORY_SHAPES,p.lastShape);p.lastGenre=genre;p.lastShape=shape.id;save();const o=readOutline(await brain.write(state.brainCfg,outlineAsk(brainCtx(s),p.premise,p.must.replace(/\n/g,'; '),genre,shape),800));if(!o)throw Error('The outline did not come back in a usable form. Tap Auto outline again.');if(!document.contains(g('planIntro')))return;g('planIntro').value=o.intro;g('planBody').value=o.body;g('planEnd').value=o.conclusion;g('planEvents').value=o.events.join('\n');read();say(`Outline written: ${genre} · ${shape.name}. Tap Auto outline again for a different one, or edit it, then write her lines.`)})};
  g('planWrite').onclick=()=>{if(!need())return;busy(g('planWrite'),'Writing…',async()=>{const p=read();if(!p.intro&&!p.body&&!p.conclusion&&!p.events.length)throw Error('Write an outline first, or tap Auto outline.');const beats=readBeats(await brain.write(state.brainCfg,scriptAsk(brainCtx(s),p,p.count),p.count*90+300),c.name);if(!beats.length)throw Error('Her lines did not come back in a usable form. Tap the button again.');if(!document.contains(g('planBeats')))return;g('planBeats').value=beatsToText(beats);read();s.plan.at=0;save();renderBook();toast(`${beats.length} lines written. Read them over and edit anything.`)})};
  g('planVoice').onclick=()=>{if(voicePrep){voicePrep.stop=true;clone.stop();return}const p=read();if(!p.beats.length)return;if(!(s.voice||'').startsWith('clone:'))return toast(`${c.name} uses a phone voice, which needs no preparing. Choose a cloned voice for her in Cast to use this.`);const btn=g('planVoice');btn.textContent='Stop';say(`Preparing voice… 0 of ${p.beats.length}. Keep this page open.`);prepareStoryVoice(s,(k,total)=>say(`Preparing voice… ${k} of ${total}. Keep this page open.`)).then(r=>{say(r.stopped?`Stopped. ${r.ready} of ${r.total} lines are prepared.`:`All ${r.total} lines are prepared in ${c.name}’s voice.`)}).catch(err=>{say('');toast('Prepare voice: '+err.message,true)}).finally(()=>{if(document.contains(btn))btn.textContent='Prepare voice'})};
  g('planUse').onclick=()=>{const p=read();if(!p.beats.length)return toast('Write her lines first.');p.at=0;s.story=true;s.brain=false;s.demo=false;save();navigate('chat');awaiting=true;setTimeout(()=>storyNext(s),500)}}
function renderBook(){const s=currentSession();app.innerHTML=`<div class="content">${top('Your storybook.','Keep the conversation. Shape it into something worth reading.')}<div class="list">${state.sessions.map(x=>`<button class="row between" data-session="${x.id}"><span>${esc(findScene(x.scene).name)} · ${esc(findCast(x.partner).name)}</span><small>${x.messages.length} messages ${x.id===state.active?'✓':''}</small></button>`).join('')}</div>${s?storyPlanCard(s):''}${s?`<div class="bookCard"><span class="eyebrow">CHAPTER DRAFT</span><p class="footerNote">Transcript is captured automatically. Narrative rewriting needs an AI connection; edit the draft here.</p><textarea class="chapter" id="draft">${esc(s.draft||storyText(s,state.cast,state.scenes))}</textarea><div class="actions"><button id="saveDraft" class="primary">Save draft</button><button id="exportText">Export text</button></div><p><button class="mini secondary" id="addLine">＋ Add companion dialogue</button> <button class="mini secondary" id="resume">Resume chat</button></p></div>`:'<div class="empty">Your first chapter starts with a conversation.</div>'}</div>`;document.querySelectorAll('[data-session]').forEach(b=>b.onclick=()=>{state.active=b.dataset.session;save();renderBook()});if(!s)return;wireStoryPlan(s);$('#saveDraft').onclick=()=>{s.draft=$('#draft').value;save();toast('Draft saved.')};$('#exportText').onclick=()=>{const url=URL.createObjectURL(new Blob([$('#draft').value],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='echo-vision-story.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#resume').onclick=()=>navigate('chat');$('#addLine').onclick=()=>{modal(`<h2>Write their next line.</h2><form id="lineForm"><label>Dialogue<textarea name="line" required maxlength="4000"></textarea></label><button class="primary wide">Add to conversation</button></form>`);$('#lineForm').onsubmit=e=>{e.preventDefault();const text=e.target.line.value.trim();if(!text)return;s.messages.push({role:'assistant',text,demo:false});save();$('#modal').close();renderBook();toast('Dialogue added to the transcript. Saved draft remains yours to edit.')}}}
view='home';render();openDB().then(async d=>{db=d;if(state.purgeAudio?.length){try{const st=d.transaction('files','readwrite').objectStore('files');for(const id of state.purgeAudio)st.delete(IDBKeyRange.bound('audio:'+id+'\n','audio:'+id+'\n\uffff'))}catch{}state.purgeAudio=[];save()}const tx=d.transaction('files'),r=tx.objectStore('files').openCursor();r.onsuccess=()=>{const cursor=r.result;if(cursor){if(!String(cursor.key).startsWith('audio:')){media[cursor.key]=URL.createObjectURL(cursor.value);mediaType[cursor.key]=cursor.value.type}cursor.continue()}else render()};clone.setStore({get:key=>new Promise(res=>{try{const q=d.transaction('files').objectStore('files').get('audio:'+key);q.onsuccess=()=>res(q.result||null);q.onerror=()=>res(null)}catch{res(null)}}),put:(key,blob)=>{try{d.transaction('files','readwrite').objectStore('files').put(blob,'audio:'+key)}catch{}}})}).catch(()=>toast('Media storage is unavailable. Text setup still works.'));
